    throw new ApiError(
      response.status,
      payload?.error?.code ?? 'api_error',
      payload?.error?.messageAr ?? payload?.error?.message ?? 'Request failed',
      payload?.error?.requestId,
    );
  }
  if (response.status === 204) return undefined as T;
  return response.json() as Promise<T>;
}

