function humanizeKey(key: string, locale: LocaleLike): string {
  const cleaned = key.replace(/[._]/g, ' ').trim();
  if (!cleaned) return key;
  if (isAr(locale)) return cleaned;
  return cleaned.replace(/\b\w/g, (ch) => ch.toUpperCase());
}

