import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const dir = 'docs/handoffs/2026-09-02-continue-0.4.42';
const src =
  'C:/Users/ameed/.cursor/projects/c-dev-BHD-R/agent-transcripts/307d3b18-d433-4130-9cd4-fbf9f887f158/307d3b18-d433-4130-9cd4-fbf9f887f158.jsonl';
const jsonlOut = path.join(dir, 'conversation-transcript.jsonl');
const mdOut = path.join(dir, 'conversation-readable.md');

function redact(text) {
  let s = String(text);
  s = s.replace(/postgres(?:ql)?:\/\/[^\s"'`\\]+/gi, '[REDACTED-DATABASE-URL]');
  s = s.replace(/DATABASE_URL\s*=\s*[^\s"'`\\]+/gi, 'DATABASE_URL=[REDACTED-DATABASE-URL]);
  s = s.replace(/(?:neon\.tech|amazonaws\.com)[^\s"'`\\]*/gi, (m) =>
    /postgres/i.test(m) ? '[REDACTED-DATABASE-HOST]' : m,
  );
  s = s.replace(
    /(?:API[_-]?KEY|SECRET|TOKEN|PASSWORD|PRIVATE[_-]?KEY)\s*[=:]\s*[^\s"'`\\]+/gi,
    (m) => m.replace(/=.+$/, '=[REDACTED]').replace(/:.+$/, ':[REDACTED]'),
  );
  s = s.replace(/\bAKIA[0-9A-Z]{16}\b/g, '[REDACTED-ACCESS-KEY-ID]');
  s = s.replace(/\b(?:sk|pk|rk)_(?:live|test)_[A-Za-z0-9]+/g, '[REDACTED-KEY]');
  s = s.replace(/\beyJ[A-Za-z0-9_-]{20,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g, '[REDACTED-JWT]');
  s = s.replace(/\b[A-Fa-f0-9]{64}\b/g, '[REDACTED-HEX-SECRET]');
  return s;
}

const raw = fs.readFileSync(src, 'utf8');
const redacted = redact(raw);
fs.writeFileSync(jsonlOut, redacted, 'utf8');

const buf = fs.readFileSync(jsonlOut);
const sha = crypto.createHash('sha256').update(buf).digest('hex');
const lines = redacted.split(/\r?\n/).filter(Boolean);

const md = [];
md.push('# نسخة مقروءة من محادثة Cursor (محدَّثة)');
md.push('');
md.push('- **المصدر:** conversation-transcript.jsonl (منقّح)');
md.push('- **تاريخ التوثيق:** 2026-09-02');
md.push('- **وقت التوثيق (مسقط / UTC+4):** 23:39');
md.push('- **معرّف المحادثة:** 307d3b18-d433-4130-9cd4-fbf9f887f158');
md.push(`- **عدد أسطر الـ JSONL:** ${lines.length}`);
md.push('- **آخر commit عند الأرشفة:** f059bc6 — show property on bookings and mark calendar booked');
md.push('');
md.push(
  '> استخراج نصوص المستخدم/المساعد. مفاتيح API وروابط قواعد البيانات استُبدلت بـ `[REDACTED-…]` قبل الرفع إلى GitHub.',
);
md.push('');

let i = 0;
let msgCount = 0;
for (const line of lines) {
  let ev;
  try {
    ev = JSON.parse(line);
  } catch {
    continue;
  }
  const role = ev.role || ev.type || 'unknown';
  const content = ev.message?.content ?? ev.content;
  const parts = [];
  if (typeof content === 'string') parts.push(content);
  else if (Array.isArray(content)) {
    for (const p of content) {
      if (typeof p === 'string') parts.push(p);
      else if (p?.type === 'text' && p.text) parts.push(p.text);
    }
  }
  const text = parts.join('\n\n').trim();
  if (!text) continue;
  msgCount += 1;
  i += 1;
  const label = role === 'user' ? 'المستخدم' : role === 'assistant' ? 'المساعد' : role;
  md.push(`## ${i}. ${label}`);
  md.push('');
  // Cap very long tool-heavy dumps for readability; keep full JSONL intact
  const clipped = text.length > 8000 ? `${text.slice(0, 8000)}\n\n… [مقتطف — الباقي في JSONL]` : text;
  md.push(clipped);
  md.push('');
}

fs.writeFileSync(mdOut, md.join('\n'), 'utf8');

const manifest = `# Manifest — 2026-09-02 continue 0.4.42 (حدّث ليلاً)

| ملف | الحجم (بايت) | ملاحظات |
| --- | ---: | --- |
| \`conversation-transcript.jsonl\` | ${buf.length} | SHA256 \`${sha}\` · ${lines.length} سطر |
| \`conversation-readable.md\` | ${fs.statSync(mdOut).size} | ${msgCount} رسالة مستخرجة |
| \`README.md\` | — | ملخص التسليم الحي |
| \`CONTINUE-PLAN-AR.md\` | — | الأولويات للجهاز الآخر |

**محادثة Cursor:** \`307d3b18-d433-4130-9cd4-fbf9f887f158\`  
**آخر commit:** \`f059bc6\`  
**أساس سابق:** \`docs/handoffs/2026-09-02-evening-home-handoff/\`  
**تحديث:** 2026-09-02 23:39 مسقط — أرشفة كاملة بعد تأكيد الحجز + بوابة المالك + i18n
`;

fs.writeFileSync(path.join(dir, 'MANIFEST.md'), manifest, 'utf8');

console.log(
  JSON.stringify(
    {
      lines: lines.length,
      messages: msgCount,
      jsonlBytes: buf.length,
      mdBytes: fs.statSync(mdOut).size,
      sha,
    },
    null,
    2,
  ),
);

