import { NextResponse } from 'next/server';
import { z } from 'zod';
import type { SessionClaims } from '@bhd-r/authz';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { clientSafeErrorCode, statusForSafeCode } from '@/lib/client-safe-error';
import { isoDateSchema, leaseTenantSchema, leaseTermsSchema } from '@/lib/lease-contract-schema';
import { reservationOwnerAction } from '@/lib/lease-reservation-lifecycle-neon';
import { guardErrorResponse, requireLiveSession } from '@/lib/next-route-guard';
import { assertRouteRateLimit, clientIp, hashRateKey } from '@/lib/route-rate-limit';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 30;

const uuid = z.string().uuid();
const requirementCode = z.string().regex(/^[a-z0-9_]{2,40}$/);

const bodySchema = z.discriminatedUnion('action', [
  z.object({ action: z.literal('approve') }).strict(),
  z
    .object({
      action: z.literal('save_contract'),
      lease: z
        .object({ unitId: uuid, tenant: leaseTenantSchema, terms: leaseTermsSchema })
        .strict()
        .optional(),
      sale: z
        .object({
          signedOn: isoDateSchema,
          amount: z
            .string()
            .trim()
            .regex(/^\d{1,12}(\.\d{1,3})?$/),
          notes: z.string().max(2000).optional(),
        })
        .strict()
        .optional(),
      requirements: z
        .array(
          z
            .object({
              code: requirementCode,
              labelAr: z.string().trim().min(2).max(120),
              labelEn: z.string().trim().max(120),
            })
            .strict(),
        )
        .max(12),
    })
    .strict(),
  z
    .object({
      action: z.literal('review_document'),
      code: requirementCode,
      decision: z.enum(['approved', 'rejected']),
      note: z.string().max(500).optional(),
    })
    .strict(),
  z.object({ action: z.literal('issue_contract') }).strict(),
  z
    .object({
      action: z.literal('record_handover'),
      on: isoDateSchema,
      recipientName: z.string().trim().min(2).max(120),
      keys: z.string().max(200).optional(),
      electricityReading: z.string().max(40).optional(),
      waterReading: z.string().max(40).optional(),
      notes: z.string().max(1000).optional(),
    })
    .strict(),
]);

/**
 * POST /api/owner/bookings/:reservationId/lifecycle
 * A website rent / purchase booking after its deposit: owner approval, contract and required
 * documents, document review, contract approval (awaits the tenant's signature), handover.
 */
export async function POST(
  request: Request,
  context: { params: Promise<{ reservationId: string }> },
) {
  if (!hasDatabaseUrl()) {
    return NextResponse.json({ error: { code: 'db_unconfigured' } }, { status: 503 });
  }

  let claims: SessionClaims;
  try {
    claims = await requireLiveSession(request, { requireCsrf: true });
  } catch (error) {
    const mapped = guardErrorResponse(error);
    return NextResponse.json(mapped.body, { status: mapped.status });
  }
  if (!claims.organizationId) {
    return NextResponse.json({ error: { code: 'organization_required' } }, { status: 400 });
  }

  const limited = assertRouteRateLimit({
    key: hashRateKey(['owner-reservation-lifecycle', claims.sub, clientIp(request)]),
    limit: 30,
    windowMs: 60_000,
  });
  if (!limited.ok) {
    return NextResponse.json(
      { error: { code: 'rate_limited' } },
      { status: 429, headers: { 'retry-after': String(limited.retryAfterSec) } },
    );
  }

  const { reservationId } = await context.params;
  if (!uuid.safeParse(reservationId).success) {
    return NextResponse.json({ error: { code: 'not_found' } }, { status: 404 });
  }
  let body: z.infer<typeof bodySchema>;
  try {
    body = bodySchema.parse(await request.json());
  } catch {
    return NextResponse.json({ error: { code: 'invalid_body' } }, { status: 400 });
  }

  try {
    return NextResponse.json(await reservationOwnerAction(claims, reservationId, body), {
      headers: { 'cache-control': 'no-store' },
    });
  } catch (error) {
    const code = clientSafeErrorCode(error, 'update_failed');
    if (code === 'update_failed') console.error('POST /api/owner/bookings/lifecycle', error);
    return NextResponse.json({ error: { code } }, { status: statusForSafeCode(code) });
  }
}

import { NextResponse } from 'next/server';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { readReservationFileForStaff } from '@/lib/lease-reservation-lifecycle-neon';
import { readClaims } from '@/lib/portal-ops-data';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 20;

const FILE = /^(?:signature|id-front|id-back|selfie|contract-signature|doc-[a-z0-9_]{2,40})$/;

/**
 * GET /api/owner/bookings/:reservationId/files/:file
 * E-signature captures (signature, ID front/back, selfie), the tenant's contract signature,
 * and documents the customer sent (`doc-<code>`) for a website rent / purchase booking.
 */
export async function GET(
  _request: Request,
  context: { params: Promise<{ reservationId: string; file: string }> },
) {
  const { reservationId, file } = await context.params;
  if (!hasDatabaseUrl() || !FILE.test(file)) {
    return NextResponse.json({ error: { code: 'not_found' } }, { status: 404 });
  }
  const claims = await readClaims();
  if (!claims) return NextResponse.json({ error: { code: 'unauthorized' } }, { status: 401 });

  try {
    const found = await readReservationFileForStaff(claims, reservationId, file);
    if (!found) return NextResponse.json({ error: { code: 'not_found' } }, { status: 404 });
    const extension = found.mimeType === 'application/pdf' ? 'pdf' : found.mimeType.split('/')[1];
    const safeName = `${file}.${extension}`;
    return new NextResponse(new Uint8Array(found.bytes), {
      headers: {
        'Content-Type': found.mimeType,
        'Content-Length': String(found.bytes.length),
        'Cache-Control': 'private, no-store',
        'X-Content-Type-Options': 'nosniff',
        'Content-Disposition': `inline; filename="${safeName}"`,
        'Content-Security-Policy': "default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'",
      },
    });
  } catch (error) {
    console.error('GET /api/owner/bookings/files failed', error);
    return NextResponse.json({ error: { code: 'load_failed' } }, { status: 500 });
  }
}

import { z } from 'zod';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { leaseBookingErrorResponse, leaseBookingJson } from '@/lib/lease-booking-route';
import { REQUIREMENT_FILE_MAX_CHARS } from '@/lib/lease-reservation-lifecycle';
import { submitReservationDocument } from '@/lib/lease-reservation-lifecycle-neon';
import { requireLiveSession } from '@/lib/next-route-guard';
import { assertRouteRateLimit, clientIp, hashRateKey } from '@/lib/route-rate-limit';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const bodySchema = z
  .object({
    code: z.string().regex(/^[a-z0-9_]{2,40}$/),
    fileName: z.string().max(200),
    dataUrl: z.string().startsWith('data:').max(REQUIREMENT_FILE_MAX_CHARS),
  })
  .strict();

/** POST — the customer sends one document the owner asked for before the contract. */
export async function POST(
  request: Request,
  context: { params: Promise<{ reference: string }> },
) {
  if (!hasDatabaseUrl()) {
    return leaseBookingJson({ error: { code: 'db_unconfigured' } }, { status: 503 });
  }

  let claims;
  try {
    claims = await requireLiveSession(request, { requireCsrf: true });
  } catch (error) {
    return leaseBookingErrorResponse(error);
  }

  const limited = assertRouteRateLimit({
    key: hashRateKey(['lease-documents', claims.sub, clientIp(request)]),
    limit: 20,
    windowMs: 60_000,
  });
  if (!limited.ok) {
    return leaseBookingJson(
      { error: { code: 'rate_limited', messageAr: 'محاولات كثيرة.' } },
      { status: 429, headers: { 'retry-after': String(limited.retryAfterSec) } },
    );
  }

  const parsed = bodySchema.safeParse(await request.json().catch(() => null));
  if (!parsed.success) {
    return leaseBookingJson(
      {
        error: {
          code: 'invalid_body',
          messageAr: 'الملف غير مكتمل أو كبير جداً — أرسل صورة أو PDF أصغر.',
        },
      },
      { status: 400 },
    );
  }

  const { reference } = await context.params;
  try {
    return leaseBookingJson(await submitReservationDocument(claims, reference, parsed.data));
  } catch (error) {
    return leaseBookingErrorResponse(error, 'request_failed');
  }
}

import { z } from 'zod';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { leaseBookingErrorResponse, leaseBookingJson } from '@/lib/lease-booking-route';
import { signReservationContract } from '@/lib/lease-reservation-lifecycle-neon';
import { requireLiveSession } from '@/lib/next-route-guard';
import { assertRouteRateLimit, clientIp, hashRateKey } from '@/lib/route-rate-limit';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const bodySchema = z
  .object({
    signaturePng: z.string().startsWith('data:image/').max(900_000),
    accepted: z.literal(true),
  })
  .strict();

/** POST — the tenant (or buyer) signs the contract the owner approved. */
export async function POST(
  request: Request,
  context: { params: Promise<{ reference: string }> },
) {
  if (!hasDatabaseUrl()) {
    return leaseBookingJson({ error: { code: 'db_unconfigured' } }, { status: 503 });
  }

  let claims;
  try {
    claims = await requireLiveSession(request, { requireCsrf: true });
  } catch (error) {
    return leaseBookingErrorResponse(error);
  }

  const limited = assertRouteRateLimit({
    key: hashRateKey(['lease-contract-sign', claims.sub, clientIp(request)]),
    limit: 8,
    windowMs: 60_000,
  });
  if (!limited.ok) {
    return leaseBookingJson(
      { error: { code: 'rate_limited', messageAr: 'محاولات كثيرة.' } },
      { status: 429, headers: { 'retry-after': String(limited.retryAfterSec) } },
    );
  }

  const parsed = bodySchema.safeParse(await request.json().catch(() => null));
  if (!parsed.success) {
    return leaseBookingJson(
      { error: { code: 'invalid_body', messageAr: 'وقّع في المساحة المخصصة ووافق على العقد.' } },
      { status: 400 },
    );
  }

  const { reference } = await context.params;
  try {
    return leaseBookingJson(
      await signReservationContract(claims, reference, {
        signaturePng: parsed.data.signaturePng,
      }),
    );
  } catch (error) {
    return leaseBookingErrorResponse(error, 'request_failed');
  }
}

