'use client';

import { useRouter } from 'next/navigation';
import { useState, type ChangeEvent } from 'react';
import { Link } from '@/i18n/navigation';
import { EsignSignaturePad } from '@/components/stays/esign/esign-signature-pad';
import { StayApprovalDesk } from '@/components/stays/stay-approval-desk';
import { useStayJourney } from '@/components/stays/stay-journey';
import { StaySendPhone } from '@/components/stays/stay-send-phone';
import { StayTrip } from '@/components/stays/stay-trip';
import { ApiError, browserNextMutation } from '@/lib/api';
import { compressImageFile } from '@/lib/compress-image';
import {
  REQUIREMENT_FILE_MAX_CHARS,
  leaseJourneyStageIndex,
  leaseJourneyStageLabels,
  type LeaseJourneyPhase,
} from '@/lib/lease-reservation-lifecycle';
import type { LeaseLifecycleView } from '@/lib/public-lease-booking-neon';

export type LeaseJourneyProps = {
  locale: 'ar' | 'en';
  referenceCode: string;
  mode: 'rent' | 'sale';
  phase: LeaseJourneyPhase;
  lifecycle: LeaseLifecycleView;
  deposit: string;
  propertyName: string;
};

function stamp(iso: string | null, ar: boolean): string {
  if (!iso) return '';
  const date = new Date(iso.length === 10 ? `${iso}T12:00:00.000Z` : iso);
  if (Number.isNaN(date.getTime())) return iso;
  return new Intl.DateTimeFormat(ar ? 'ar-OM-u-nu-latn' : 'en-GB', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    timeZone: 'Asia/Muscat',
  }).format(date);
}

function readAsDataUrl(file: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result));
    reader.onerror = () => reject(new Error('read_failed'));
    reader.readAsDataURL(file);
  });
}

function errorText(error: unknown, ar: boolean): string {
  if (error instanceof ApiError) return error.message;
  return ar ? 'تعذّر الإرسال — تحقق من الاتصال وأعد المحاولة.' : 'Could not send — try again.';
}

type Screen = {
  headline: string;
  body: string;
  guide?: string[];
  scene?: 'send' | 'desk' | 'contract' | 'handover' | 'keys';
  sceneDone?: boolean;
  sceneStatus?: string;
  action?: 'sign_terms' | 'view_terms' | 'documents' | 'sign_contract' | 'view_contract';
};

/** Warm, plain wording for each stage the customer can open. */
function leaseScreens(props: LeaseJourneyProps): Array<Screen | null> {
  const { phase, lifecycle, mode, deposit } = props;
  const ar = props.locale === 'ar';
  const sale = mode === 'sale';
  const t = (arText: string, enText: string) => (ar ? arText : enText);
  const current = leaseJourneyStageIndex(phase);
  const contractWord = sale ? t('عقد البيع', 'sale contract') : t('عقد الإيجار', 'lease');
  const requirements = lifecycle.requirements;

  const booking: Screen =
    phase === 'awaiting_terms_signature'
      ? {
          headline: t('خطوة صغيرة تفصلك عن حجزك 🖊️', 'One small step to secure it 🖊️'),
          body: t(
            `استلمنا العربون ${deposit} بأمان. بقي أن توقّع اتفاقية الحجز إلكترونياً مع صورة هويتك — دقيقتان لا أكثر، ثم نرسل حجزك للمالك.`,
            `We safely received your ${deposit} deposit. Just e-sign the booking agreement with your ID — two minutes — and we send it to the owner.`,
          ),
          scene: 'send',
          sceneStatus: t('بانتظار توقيعك', 'Awaiting your signature'),
          action: 'sign_terms',
        }
      : {
          headline: t('تم الحجز بنجاح 🎉', 'Booked successfully 🎉'),
          body: t(
            `استلمنا العربون ${deposit} ووقّعتَ اتفاقية الحجز إلكترونياً. ${sale ? 'العقار' : 'الوحدة'} محجوزة باسمك الآن، ولن يحجزها أحد غيرك.`,
            `We received your ${deposit} deposit and you e-signed the booking agreement. It is now reserved in your name only.`,
          ),
          scene: 'send',
          sceneDone: true,
          sceneStatus: t('تم الحجز', 'Booked'),
          action: 'view_terms',
        };

  const approval: Screen | null =
    current < 1
      ? null
      : phase === 'awaiting_owner_approval'
        ? {
            headline: t('حجزك على مكتب المالك الآن ☕', 'Your booking is on the owner’s desk ☕'),
            body: t(
              'أرسلنا حجزك إلى المالك ليعتمده. عادةً لا يطول الأمر — وسيتغيّر هذا المشهد فور الاعتماد، فعُد إلى هذه الصفحة متى شئت.',
              'We sent your booking to the owner for approval. It rarely takes long — this scene changes the moment they approve.',
            ),
            scene: 'desk',
            sceneStatus: t('قيد المراجعة', 'Under review'),
          }
        : {
            headline: t('مبروك! المالك اعتمد حجزك ✅', 'Congratulations! The owner approved ✅'),
            body: t(
              `اعتمد المالك حجزك${lifecycle.approvedAt ? ` في ${stamp(lifecycle.approvedAt, ar)}` : ''}. حجزك الآن معتمد، والخطوة التالية أن يُعدّ المالك ${contractWord}.`,
              `The owner approved your booking${lifecycle.approvedAt ? ` on ${stamp(lifecycle.approvedAt, ar)}` : ''}. Next, the owner prepares your ${contractWord}.`,
            ),
            scene: 'desk',
            sceneDone: true,
            sceneStatus: t('معتمد', 'Approved'),
          };

  let documents: Screen | null = null;
  if (current >= 2) {
    if (phase === 'awaiting_contract_draft') {
      documents = {
        headline: t('المالك يجهّز عقدك الآن 📝', 'The owner is preparing your contract 📝'),
        body: t(
          `حجزك معتمد وفي انتظار قيام المالك بعمل ${contractWord}. سيحدد المالك المستندات اللازمة، وستظهر لك هنا لترفعها بلمسة.`,
          `Your booking is approved and waiting for the owner to draw up the ${contractWord}. Any documents needed will appear here.`,
        ),
        scene: 'contract',
        sceneStatus: t('قيد الإعداد', 'Being prepared'),
      };
    } else if (phase === 'awaiting_documents') {
      const rejected = requirements.some((item) => item.status === 'rejected');
      documents = {
        headline: rejected
          ? t('مستند يحتاج نسخة أوضح 🔁', 'One document needs a clearer copy 🔁')
          : t('جهّز مستنداتك… ونحن معك خطوة بخطوة 📎', 'Your documents, step by step 📎'),
        body: rejected
          ? t(
              'راجع المالك ما أرسلت وطلب بديلاً لمستند — ستجد السبب بجانبه. أعد رفعه وسنُبلغ المالك فوراً.',
              'The owner asked for a replacement — the reason is next to it. Upload again and we tell the owner right away.',
            )
          : t(
              `ليكتمل ${contractWord}، يحتاج المالك المستندات التالية. صوّرها بهاتفك أو ارفع ملف PDF — كل مستند يصل للمالك مباشرة.`,
              `To complete the ${contractWord}, the owner needs the documents below. Snap them with your phone or upload a PDF.`,
            ),
        action: 'documents',
      };
    } else if (phase === 'awaiting_documents_review') {
      documents = {
        headline: t('وصلت مستنداتك، والمالك يراجعها 🔍', 'Documents received — under review 🔍'),
        body: t(
          'شكراً لك! أرسلت كل المستندات المطلوبة، وهي الآن قيد مراجعة المالك. إن احتاج أي تعديل ستجده هنا.',
          'Thank you! Everything requested is in and the owner is reviewing it.',
        ),
        action: 'documents',
      };
    } else {
      documents = {
        headline: t('مستنداتك مكتملة ومقبولة 👌', 'Documents complete and accepted 👌'),
        body: requirements.length
          ? t('قبل المالك كل مستنداتك. أحسنت!', 'The owner accepted all your documents. Well done!')
          : t('لم يطلب المالك مستندات إضافية.', 'The owner did not need extra documents.'),
        action: requirements.length ? 'documents' : undefined,
      };
    }
  }

  let contract: Screen | null = null;
  if (current >= 3) {
    if (phase === 'awaiting_contract_approval') {
      contract = {
        headline: t('العقد في مرحلة الاعتماد ✍️', 'Your contract is being approved ✍️'),
        body: t(
          `مستنداتك مقبولة، والمالك يضع اللمسات الأخيرة على ${contractWord} ليعتمده. سيصلك هنا للتوقيع فور اعتماده.`,
          `Your documents are accepted and the owner is finalising the ${contractWord}. It comes here for your signature once approved.`,
        ),
        scene: 'contract',
        sceneStatus: t('بانتظار اعتماد المالك', 'Awaiting owner approval'),
      };
    } else if (phase === 'awaiting_tenant_signature') {
      contract = {
        headline: t('عقدك جاهز وينتظر توقيعك ✨', 'Your contract is ready for your signature ✨'),
        body: t(
          `اعتمد المالك ${contractWord} ${lifecycle.contract?.reference ?? ''} ووقّعه. اقرأه بتمعّن، ثم وقّع بإصبعك — وبتوقيعك يصبح العقد موقّعاً إلكترونياً من الطرفين.`,
          `The owner approved and signed ${lifecycle.contract?.reference ?? 'the contract'}. Read it carefully, then sign with your finger — it becomes signed by both parties.`,
        ),
        scene: 'contract',
        sceneStatus: t('بانتظار توقيع الطرف الثاني', 'Awaiting second-party signature'),
        action: 'sign_contract',
      };
    } else {
      contract = {
        headline: t('عقدك موقّع إلكترونياً من الطرفين 🤝', 'Signed electronically by both parties 🤝'),
        body: t(
          `وقّعتَ ${contractWord} ${lifecycle.contract?.reference ?? ''}${lifecycle.tenantSignedAt ? ` في ${stamp(lifecycle.tenantSignedAt, ar)}` : ''}، وأصبح نافذاً وموقّعاً من الطرفين. احتفظ به دائماً في متناول يدك.`,
          `You signed ${lifecycle.contract?.reference ?? 'the contract'}; it is now in force and signed by both parties.`,
        ),
        scene: 'contract',
        sceneDone: true,
        sceneStatus: t('موقّع من الطرفين', 'Signed by both parties'),
        action: 'view_contract',
      };
    }
  }

  let handover: Screen | null = null;
  if (current >= 4) {
    handover = lifecycle.handover
      ? {
          headline: sale
            ? t('مبروك تملّك عقارك الجديد 🏡', 'Congratulations on your new property 🏡')
            : t('أهلاً بك في بيتك الجديد 🏡', 'Welcome to your new home 🏡'),
          body: t(
            `تم تسليم العقار في ${stamp(lifecycle.handover.on, ar)} واستلمه ${lifecycle.handover.recipientName}${lifecycle.handover.keys ? ` (${lifecycle.handover.keys})` : ''}. نتمنى لك فيه أياماً سعيدة ومباركة.`,
            `Handed over on ${stamp(lifecycle.handover.on, ar)} to ${lifecycle.handover.recipientName}. Wishing you happy days there.`,
          ),
          guide: lifecycle.handover.notes ? [lifecycle.handover.notes] : undefined,
          scene: 'keys',
          sceneDone: true,
          sceneStatus: t('تم التسليم', 'Handed over'),
          action: 'view_contract',
        }
      : {
          headline: t('اقتربت لحظة استلام المفاتيح 🔑', 'Almost time for the keys 🔑'),
          body: t(
            'العقد موقّع من الطرفين. سيتواصل معك المالك لترتيب موعد تسليم العقار وقراءة العدادات.',
            'The contract is signed by both parties. The owner will contact you to arrange the handover.',
          ),
          guide: [
            t('احمل بطاقتك الشخصية عند الاستلام.', 'Bring your ID to the handover.'),
            t('راجع حالة العقار ودوّن أي ملاحظة.', 'Check the premises and note anything.'),
            t('تأكد من تسجيل قراءات الكهرباء والماء.', 'Make sure meter readings are recorded.'),
          ],
          scene: 'handover',
          sceneStatus: t('بانتظار التسليم', 'Awaiting handover'),
          action: 'view_contract',
        };
  }

  return [booking, approval, documents, contract, handover];
}

export function leaseJourneySteps(props: LeaseJourneyProps) {
  const ar = props.locale === 'ar';
  const current = leaseJourneyStageIndex(props.phase);
  const labels = leaseJourneyStageLabels(props.mode === 'sale', ar);
  const details = [
    null,
    props.lifecycle.approvedAt ? stamp(props.lifecycle.approvedAt, ar) : null,
    null,
    props.lifecycle.tenantSignedAt ? stamp(props.lifecycle.tenantSignedAt, ar) : null,
    props.lifecycle.handover ? stamp(props.lifecycle.handover.on, ar) : null,
  ];
  return labels.map((label, index) => ({
    label,
    state: (index < current ? 'done' : index === current ? 'current' : 'upcoming') as
      | 'done'
      | 'current'
      | 'upcoming',
    detail: details[index] ?? null,
  }));
}

export function leaseJourneyInitialStep(phase: LeaseJourneyPhase): number {
  return Math.min(Math.max(leaseJourneyStageIndex(phase), 0), 4);
}

export function leaseJourneyReachable(props: LeaseJourneyProps): boolean[] {
  return leaseScreens(props).map((screen) => screen !== null);
}

/** The message card under the hero: the selected stage's scene, words and next action. */
export function LeaseJourneyCard(props: LeaseJourneyProps) {
  const { selected, initial, select } = useStayJourney();
  const ar = props.locale === 'ar';
  const screens = leaseScreens(props);
  const labels = leaseJourneyStageLabels(props.mode === 'sale', ar);
  const screen = screens[selected] ?? screens[initial];
  if (!screen) return null;
  const past = selected !== initial;
  const sale = props.mode === 'sale';
  const plate = props.referenceCode;

  return (
    <section
      key={selected}
      className={`guest-stay-detail__greeting guest-stay-detail__greeting--confirmed${
        past ? ' guest-stay-detail__greeting--past' : ''
      }`}
      aria-live="polite"
    >
      {past ? (
        <div className="guest-stay-detail__replay">
          <span>
            {ar
              ? `هكذا بدت لك مرحلة «${labels[selected] ?? ''}»`
              : `How the “${labels[selected] ?? ''}” step looked to you`}
          </span>
          <button type="button" onClick={() => select(initial)}>
            {ar ? 'العودة إلى المرحلة الحالية' : 'Back to where you are now'}
          </button>
        </div>
      ) : null}
      {screen.scene === 'send' ? (
        <StaySendPhone
          moment={{ mode: 'instant', status: screen.sceneStatus ?? '' }}
          plateNo={plate}
          ar={ar}
          labels={{
            screen: sale ? (ar ? 'حجز شراء' : 'PURCHASE') : ar ? 'حجز إيجار' : 'RENT BOOKING',
            button: ar ? 'ادفع العربون' : 'Pay deposit',
            sent: ar ? 'تم الحجز ✓' : 'Booked ✓',
            type: ar ? 'إتمام الحجز' : 'Booking',
          }}
        />
      ) : null}
      {screen.scene === 'desk' ? (
        <StayApprovalDesk
          moment={{ signed: Boolean(screen.sceneDone), status: screen.sceneStatus ?? '' }}
          plateNo={plate}
          ar={ar}
          screenTitle={sale ? (ar ? 'حجز شراء' : 'PURCHASE') : ar ? 'حجز إيجار' : 'RENT BOOKING'}
        />
      ) : null}
      {screen.scene === 'contract' ? (
        <StayApprovalDesk
          moment={{ signed: Boolean(screen.sceneDone), status: screen.sceneStatus ?? '' }}
          plateNo={plate}
          ar={ar}
          screenTitle={sale ? (ar ? 'عقد البيع' : 'SALE CONTRACT') : ar ? 'عقد الإيجار' : 'LEASE'}
          typeLabel={sale ? (ar ? 'عقد البيع' : 'Sale contract') : ar ? 'عقد الإيجار' : 'Lease'}
        />
      ) : null}
      {screen.scene === 'handover' || screen.scene === 'keys' ? (
        <StayTrip
          moment={{
            kind: screen.scene === 'keys' ? 'arrive' : 'parked',
            status: screen.sceneStatus ?? '',
          }}
          plateNo={plate}
          ar={ar}
          typeLabel={ar ? 'تسليم العقار' : 'Handover'}
        />
      ) : null}
      <h2>{screen.headline}</h2>
      <p>{screen.body}</p>
      {screen.guide ? (
        <ol className="guest-stay-detail__guide">
          {screen.guide.map((line) => (
            <li key={line}>{line}</li>
          ))}
        </ol>
      ) : null}
      {screen.action === 'sign_terms' ? (
        <Link
          className="button button--primary guest-stay-detail__rebook"
          href={`/book/sign?ref=${encodeURIComponent(plate)}`}
        >
          {ar ? 'توقيع اتفاقية الحجز' : 'Sign the booking agreement'}
        </Link>
      ) : null}
      {screen.action === 'view_terms' ? (
        <Link
          className="button button--quiet guest-stay-detail__rebook"
          href={`/book/sign?ref=${encodeURIComponent(plate)}`}
        >
          {ar ? 'عرض اتفاقية الحجز الموقّعة' : 'View signed booking agreement'}
        </Link>
      ) : null}
      {screen.action === 'documents' && !past ? <LeaseDocuments {...props} /> : null}
      {screen.action === 'documents' && past ? <LeaseDocumentList {...props} /> : null}
      {screen.action === 'sign_contract' && !past ? <LeaseContractSign {...props} /> : null}
      {screen.action === 'view_contract' && props.lifecycle.contract ? (
        <Link
          className="button button--quiet guest-stay-detail__rebook"
          href={`/tenant/contracts/${encodeURIComponent(props.lifecycle.contract.id)}`}
        >
          {ar ? 'عرض العقد الموقّع' : 'View signed contract'}
        </Link>
      ) : null}
    </section>
  );
}

const REQUIREMENT_STATUS: Record<string, [string, string]> = {
  pending: ['مطلوب', 'Needed'],
  submitted: ['أُرسل — قيد المراجعة', 'Sent — under review'],
  approved: ['مقبول ✓', 'Accepted ✓'],
  rejected: ['مطلوب بديل', 'Replacement needed'],
};

function LeaseDocumentList({ lifecycle, locale }: LeaseJourneyProps) {
  const ar = locale === 'ar';
  return (
    <ul className="lease-docs">
      {lifecycle.requirements.map((item) => (
        <li key={item.code} className={`lease-docs__item lease-docs__item--${item.status}`}>
          <strong>{ar ? item.labelAr : item.labelEn || item.labelAr}</strong>
          <span>{REQUIREMENT_STATUS[item.status]?.[ar ? 0 : 1]}</span>
        </li>
      ))}
    </ul>
  );
}

function LeaseDocuments({ lifecycle, locale, referenceCode }: LeaseJourneyProps) {
  const ar = locale === 'ar';
  const router = useRouter();
  const [busy, setBusy] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  async function upload(code: string, event: ChangeEvent<HTMLInputElement>) {
    const picked = event.target.files?.[0];
    event.target.value = '';
    if (!picked) return;
    setError(null);
    setBusy(code);
    try {
      const file = picked.type.startsWith('image/') ? await compressImageFile(picked) : picked;
      if (file.type !== 'application/pdf' && !file.type.startsWith('image/')) {
        throw new Error(ar ? 'أرسل صورة أو ملف PDF.' : 'Send an image or a PDF.');
      }
      const dataUrl = await readAsDataUrl(file);
      if (dataUrl.length > REQUIREMENT_FILE_MAX_CHARS) {
        throw new Error(
          ar
            ? 'الملف كبير جداً (الحد نحو 1 ميغابايت). صوّره بدقة أقل أو قسّم ملف PDF.'
            : 'The file is too large (about 1 MB max).',
        );
      }
      await browserNextMutation(
        `/api/public/bookings/deposits/${encodeURIComponent(referenceCode)}/documents`,
        {
          method: 'POST',
          body: JSON.stringify({ code, fileName: picked.name.slice(0, 200), dataUrl }),
        },
      );
      router.refresh();
    } catch (caught) {
      setError(caught instanceof ApiError ? errorText(caught, ar) : (caught as Error).message);
    } finally {
      setBusy(null);
    }
  }

  return (
    <div className="lease-docs-wrap">
      {error ? (
        <p className="notice notice--error" role="alert">
          {error}
        </p>
      ) : null}
      <ul className="lease-docs">
        {lifecycle.requirements.map((item) => {
          const canUpload = item.status !== 'approved';
          return (
            <li key={item.code} className={`lease-docs__item lease-docs__item--${item.status}`}>
              <div className="lease-docs__text">
                <strong>{ar ? item.labelAr : item.labelEn || item.labelAr}</strong>
                <span>{REQUIREMENT_STATUS[item.status]?.[ar ? 0 : 1]}</span>
                {item.status === 'rejected' && item.note ? (
                  <small>
                    {ar ? 'ملاحظة المالك: ' : 'Owner note: '}
                    {item.note}
                  </small>
                ) : null}
                {item.fileName && item.status !== 'rejected' ? (
                  <small dir="auto">{item.fileName}</small>
                ) : null}
              </div>
              {canUpload ? (
                <label className="button button--quiet lease-docs__upload">
                  {busy === item.code
                    ? ar
                      ? 'جارٍ الإرسال…'
                      : 'Sending…'
                    : item.status === 'pending'
                      ? ar
                        ? 'رفع المستند'
                        : 'Upload'
                      : ar
                        ? 'استبدال'
                        : 'Replace'}
                  <input
                    type="file"
                    accept="image/*,application/pdf"
                    hidden
                    disabled={busy !== null}
                    onChange={(event) => void upload(item.code, event)}
                  />
                </label>
              ) : null}
            </li>
          );
        })}
      </ul>
    </div>
  );
}

function LeaseContractSign({ lifecycle, locale, referenceCode, mode }: LeaseJourneyProps) {
  const ar = locale === 'ar';
  const router = useRouter();
  const [accepted, setAccepted] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const contract = lifecycle.contract;
  if (!contract) return null;

  async function sign(signaturePng: string) {
    if (!accepted) {
      setError(
        ar ? 'أكّد أولاً أنك قرأت العقد ووافقت عليه.' : 'First confirm you read and accept it.',
      );
      return;
    }
    setBusy(true);
    setError(null);
    try {
      await browserNextMutation(
        `/api/public/bookings/deposits/${encodeURIComponent(referenceCode)}/contract-sign`,
        { method: 'POST', body: JSON.stringify({ signaturePng, accepted: true }) },
      );
      router.refresh();
    } catch (caught) {
      setError(errorText(caught, ar));
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="lease-sign">
      <Link
        className="button button--quiet"
        href={`/tenant/contracts/${encodeURIComponent(contract.id)}`}
        target="_blank"
      >
        {ar ? `اقرأ العقد ${contract.reference} كاملاً` : `Read ${contract.reference} in full`}
      </Link>
      <label className="lease-sign__accept">
        <input
          type="checkbox"
          checked={accepted}
          onChange={(event) => setAccepted(event.target.checked)}
        />
        <span>
          {ar
            ? `قرأتُ ${mode === 'sale' ? 'عقد البيع' : 'عقد الإيجار'} وأوافق على جميع بنوده، وأقرّ بأن توقيعي الإلكتروني ملزم كتوقيعي بخط اليد.`
            : 'I have read the contract, accept all its terms, and agree my e-signature binds me like my handwritten one.'}
        </span>
      </label>
      {error ? (
        <p className="notice notice--error" role="alert">
          {error}
        </p>
      ) : null}
      {busy ? (
        <p className="muted">{ar ? 'جارٍ تسجيل توقيعك…' : 'Recording your signature…'}</p>
      ) : (
        <EsignSignaturePad locale={locale} onAccept={(png) => void sign(png)} />
      )}
    </div>
  );
}

const fs = require('fs');
const p = 'apps/web/src/components/lease-journey.tsx';
const lines = fs.readFileSync(p, 'utf8').split('\n');
const idx = (prefix) => {
  const i = lines.findIndex((line) => line.startsWith(prefix));
  if (i < 0) throw new Error(prefix);
  return i;
};
const propsStart = idx('export type LeaseJourneyProps');
const stampStart = idx('function stamp(');
const readStart = idx('function readAsDataUrl(');
const screenStart = idx('type Screen = {');
const cardStart = idx('/** The message card');

const propsBlock = lines.slice(propsStart, stampStart);
const stampBlock = lines.slice(stampStart, readStart);
const readBlock = lines.slice(readStart, screenStart);
const sharedBlock = lines.slice(screenStart, cardStart);

const header = [
  "import {",
  "  leaseJourneyStageIndex,",
  "  leaseJourneyStageLabels,",
  "  type LeaseJourneyPhase,",
  "} from '@/lib/lease-reservation-lifecycle';",
  "import type { LeaseLifecycleView } from '@/lib/public-lease-booking-neon';",
  '',
];
const shared = [
  ...header,
  ...propsBlock,
  ...stampBlock.map((line) => line.replace('function stamp(', 'export function journeyStamp(')),
  ...sharedBlock
    .map((line) => line.replace('type Screen = {', 'export type LeaseJourneyScreen = {'))
    .map((line) => line.replace(/Array<Screen \| null>/g, 'Array<LeaseJourneyScreen | null>'))
    .map((line) => line.replace(/: Screen( \| null)? =/g, ': LeaseJourneyScreen$1 ='))
    .map((line) => line.replace('function leaseScreens(', 'export function leaseScreens('))
    .map((line) => line.replace(/\bstamp\(/g, 'journeyStamp(')),
];
fs.writeFileSync('apps/web/src/lib/lease-journey-screens.ts', shared.join('\n'));

const rest = [
  ...lines.slice(0, propsStart),
  ...readBlock,
  ...lines.slice(cardStart),
];
fs.writeFileSync(p, rest.join('\n'));
console.log('ok');

