const fs = require('node:fs');
const path = require('node:path');
const QRCode = require(require.resolve('qrcode', { paths: [path.join(__dirname, '../apps/web')] }));

const root = path.join(__dirname, '..');
const css = fs.readFileSync(path.join(root, 'apps/web/src/app/globals.css'), 'utf8');
const start = css.indexOf('/* Property location: map');
const end = css.indexOf('.contract-doc__important');
const block = css.slice(start, end);
const logo = fs.readFileSync(path.join(root, 'apps/web/public/brand/bhd-official-symbol.svg'));
const logoUrl = `data:image/svg+xml;base64,${logo.toString('base64')}`;

const lat = 23.588;
const lng = 58.3829;
const ZOOM = 16;
const count = 2 ** ZOOM;
const r = (lat * Math.PI) / 180;
const x = ((lng + 180) / 360) * count;
const y = ((1 - Math.log(Math.tan(r) + 1 / Math.cos(r)) / Math.PI) / 2) * count;
let tiles = '';
for (let row = -1; row <= 1; row += 1) {
  for (let col = -2; col <= 2; col += 1) {
    const tx = Math.floor(x) + col;
    const ty = Math.floor(y) + row;
    tiles += `<img src="https://tile.openstreetmap.org/${ZOOM}/${tx}/${ty}.png" width="256" height="256" alt="" style="left:${Math.round((tx - x) * 256)}px;top:${Math.round((ty - y) * 256)}px">`;
  }
}

(async () => {
  const url = `https://www.google.com/maps?q=${lat},${lng}`;
  const qr = await QRCode.toString(url, {
    type: 'svg',
    margin: 1,
    errorCorrectionLevel: 'Q',
    color: { dark: '#0b3d2a', light: '#ffffff' },
  });
  const html = `<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><style>
body{font-family:system-ui;background:#f3efe4;padding:2rem}
.page{max-width:820px;margin:auto;padding:2rem;background:#fffdf7;border:1px solid #a8834a}
${block}</style></head><body><div class="page"><h2>ثانياً: العين المؤجَّرة</h2>
<figure class="loc-map"><a class="loc-map__map" href="${url}"><span class="loc-map__tiles">${tiles}</span>
<span class="loc-map__veil"></span><img class="loc-map__watermark" src="${logoUrl}" alt="">
<span class="loc-map__pin"><span class="loc-map__pulse"></span><svg viewBox="0 0 40 52" width="40" height="52"><path d="M20 51C20 51 37 31.5 37 19A17 17 0 0 0 3 19c0 12.5 17 32 17 32Z" fill="#0b3d2a" stroke="#ffffff" stroke-width="2.5"/><circle cx="20" cy="19" r="10.5" fill="#ffffff"/><path d="M14.5 20.5 20 15.5l5.5 5v5.5h-11Z" fill="#08a39f"/><rect x="18.3" y="22" width="3.4" height="4" fill="#ffffff"/></svg></span>
<span class="loc-map__brand"><img src="${logoUrl}" alt="" width="54" height="17"><i>R</i></span>
<span class="loc-map__attrib" dir="ltr">© OpenStreetMap</span></a>
<a class="loc-map__qr" href="${url}"><span class="loc-map__qr-code">${qr}</span><small><span lang="ar">امسح لفتح موقع العقار</span><span lang="en">Scan to open the location</span></small></a>
<figcaption class="loc-map__caption"><strong><span lang="ar">موقع العقار</span><span lang="en">Property location</span></strong><bdi dir="ltr">${lat.toFixed(6)}, ${lng.toFixed(6)}</bdi><a href="${url}"><span lang="ar">فتح في خرائط Google</span><span lang="en">Open in Google Maps</span></a></figcaption></figure></div></body></html>`;
  fs.writeFileSync(path.join(root, 'scripts/.tmp-locmap-preview.html'), html);
  console.log('ok');
})();

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');

http
  .createServer((_req, res) => {
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(fs.readFileSync(path.join(__dirname, '.tmp-locmap-preview.html')));
  })
  .listen(4789, () => console.log('listening 4789'));
